-- Add PP241 (Public Policy Communications) and PP226 (Judicial Reform and Policy) from OT lesson pages.
-- Id-based + idempotent (drops any existing pp241/pp226 first); pure-ASCII JSON literal (clipboard-safe).
update public.catalog set data = jsonb_set(
  data, '{subjects}',
  (select coalesce(jsonb_agg(s), '[]'::jsonb) from jsonb_array_elements(data->'subjects') s where s->>'id' not in ('pp241', 'pp226'))
  || $j$[{"id":"pp241","name":"PP241: Public Policy Communications","code":"Communications","color":"#5e3a6b","icon":"","lus":[{"id":"pp241_lu01","title":"How To Write a Policy Brief","url":"https://opentakshashila.net/posts/pgp10-how-to-write-a-policy-brief-speaker-ganesh-chakravarthi-103328302","selfStudy":false,"outcomes":[],"mandatory":[],"recommended":[{"id":"pp241_lu01_r01","name":"Protecting Civilians in Disasters and Conflicts","desc":"Brookings","url":"https://www.brookings.edu/articles/protecting-civilians-in-disasters-and-conflicts/"},{"id":"pp241_lu01_r02","name":"Locally Led Development in a Time of Disruption","desc":"Brookings","url":"https://www.brookings.edu/articles/locally-led-development-in-a-time-of-disruption/"},{"id":"pp241_lu01_r03","name":"UN DESA Policy Brief No. 151: Why Indigenous Languages Matter","desc":"UN DESA - International Decade on Indigenous Languages 2022-2032","url":"https://desapublications.un.org/policy-briefs/un-desa-policy-brief-no-151-why-indigenous-languages-matter-international-decade-0"},{"id":"pp241_lu01_r04","name":"20 Best Data Storytelling Examples","desc":"Juice Analytics","url":"https://www.juiceanalytics.com/writing/20-best-data-storytelling-examples"}]}]},{"id":"pp226","name":"PP226: Judicial Reform and Policy","code":"Judicial Reform","color":"#4b5563","icon":"","lus":[{"id":"pp226_lu01","title":"Diagnosing the System: Architecture, Capacity, and the IJR as a Measurement Instrument","url":"https://opentakshashila.net/posts/pgp10-diagnosing-the-system-architecture-capacity-and-the-ijr-as-a-measurement-instrument","selfStudy":false,"outcomes":[],"mandatory":[{"id":"pp226_lu01_m01","name":"Why Does the Indian State Both Fail and Succeed?","desc":"Devesh Kapur, JEP 34(1), 2020","url":"https://www.aeaweb.org/articles?id=10.1257/jep.34.1.31"}],"recommended":[{"id":"pp226_lu01_r01","name":"India Justice Report 2025: Full Report","desc":"Read the Executive Summary and Methodology (~25 pages)","url":"https://indiajusticereport.org"},{"id":"pp226_lu01_r02","name":"India Justice Report - Methodology","desc":"What each of the five indicators measures","url":"https://indiajusticereport.org/methodology"},{"id":"pp226_lu01_r03","name":"The State of the Indian Judiciary","desc":"DAKSH, 2016","url":"https://www.dakshindia.org/wp-content/uploads/2023/02/State-of-the-Judiciary.pdf"}]}]}]$j$::jsonb
) where id = 1;
